#!/usr/bin/env bash
# Campaign 23: the gate and hold smoke, the real table path, then just-in-time reads with the gate and the hold (results/campaign23/DECISIONS.md). Waits for campaign 22 unless GO is set.
#   host: docker exec -d sglang_hicache bash -c 'nohup bash /sgl-workspace/sglang/agent_cache/frozen/oracle_scripts_staging/c23_engine/c23.sh >> /sgl-workspace/sglang/agent_cache/results/campaign23/launcher.log 2>&1'
# While waiting: touch results/campaign23/GO to start now, or results/campaign23/CANCEL to give up. Resumable through results/campaign23/manifest.txt.
# Do not edit this file or agent_cache/scripts/ while it runs.
# Stop: pkill -f "[c]23.sh"; pkill -f "^bash [r]un_compare.sh"; pkill -f "[r]eplay_agentic.py"; bash stop_server.sh
set -uo pipefail
AC=/sgl-workspace/sglang/agent_cache
CD=$AC/results/campaign23
ENGINE=$(ls -d "$AC/frozen/engine_owned_20261101/python") || { echo "C23 STOP: frozen engine missing"; exit 1; }
mkdir -p "$CD"; touch "$CD/manifest.txt"
echo "C23 WAITING $(date -u +%FT%TZ) for campaign 22"
while :; do
  [ -f "$CD/CANCEL" ] && { echo "C23 CANCELLED $(date -u +%FT%TZ)"; exit 0; }
  [ -f "$CD/GO" ] && break
  grep -q '^C22 ALL DONE' "$AC/results/campaign22/launcher.log" && break
  grep -qE '^C22 .*(STOP|NOT STARTED|CANCELLED)' "$AC/results/campaign22/launcher.log" && { echo "C23 NOT STARTED $(date -u +%FT%TZ): campaign 22 did not finish"; exit 1; }
  sleep 60
done
for i in $(seq 1 60); do pgrep -f '^bash run_compare.sh' > /dev/null || break; sleep 10; done
if pgrep -f '^bash run_compare.sh' > /dev/null; then echo "C23 STOP $(date -u +%FT%TZ): run_compare.sh is still running"; exit 1; fi
cd "$AC/scripts" || exit 1
grep -q 'three_tier_wc_oracle_v2_nu_owned' start_server.sh || { echo "C23 STOP: scripts/start_server.sh lacks the new arms"; exit 1; }
[ -f "$CD/scripts_at_launch.tgz" ] || tar czf "$CD/scripts_at_launch.tgz" --exclude='__pycache__' -C "$AC" scripts

run_arm() {   # <manifest label> <server arm> <users in session> <host GB, empty for the level's> <ORACLE_HINTS> <HINTS> <HINT_POINT or empty> <timeout s>
  local L=$1 A=$2 N=$3 G=$4 OH=$5 H=$6 P=$7 T=$8 LOG IOS rc CMP
  grep -q "^$L " "$CD/manifest.txt" && { echo "C23 $L already done"; return 0; }
  LOG="$CD/driver_${L}_$(date -u +%m%d_%H%M%S).log"
  nohup iostat -dxt vdc 10 >> "$CD/iostat_vdc.log" 2>&1 < /dev/null & IOS=$!
  echo "C23 $L LAUNCH $(date -u +%FT%TZ) arm $A engine $ENGINE -> $LOG"
  ARMS="$A" LEVEL=NAT160 HOST_GB="$G" MODEL=Qwen/Qwen3-30B-A3B-Instruct-2507 CTX=131072 KV_DTYPE=auto TEMPLATE= L3_CLEANER_PCT=70,60 \
    TRACE="$AC/traces/lmcache_agentic_trace_262k.json" USERS=768 TURNS=50 ARRIVAL=0.1 GAP=10 C="$N" SEED=0 \
    ORACLE_HINTS="$OH" HINTS="$H" HINT_POINT="$P" CLIENT_TIMEOUT="$T" SGLANG_TIMEOUT_KEEP_ALIVE=3600 ENGINE_PYTHONPATH="$ENGINE" \
    bash run_compare.sh > "$LOG" 2>&1
  rc=$?
  kill "$IOS" 2>/dev/null
  CMP=$(grep -a '^compare dir: ' "$LOG" | cut -d' ' -f3)
  if [ -n "$CMP" ] && [ -s "$CMP/manifest.txt" ]; then
    awk -v L="$L" 'NR == 1 { print L, $2, $3 }' "$CMP/manifest.txt" >> "$CD/manifest.txt"
    cp "$CMP/config.txt" "$CD/config_$L.txt"
    echo "C23 $L DONE $(date -u +%FT%TZ) rc=$rc compare dir $CMP"
  else
    echo "C23 $L STOP $(date -u +%FT%TZ) rc=$rc, no manifest: read $LOG"
    return 1
  fi
}

# The table path must work before the arms that rely on it: plans only from the engine's own pick, no tracebacks.
smoke_ok() {
  local R n p tb
  R=$AC/results/$(awk '$1 == "table_smoke" { print $2 }' "$CD/manifest.txt")
  n=$(grep -ac 'HICACHE_EVT ntp_pick' "$R/server.log"); p=$(grep -ac 'HICACHE_EVT ntp_plan' "$R/server.log"); tb=$(grep -ac 'Traceback' "$R/server.log")
  if [ "$n" -gt 100 ] && [ "$p" -gt 100 ] && [ "$tb" -eq 0 ]; then echo "C23 smoke ok: $n picks, $p plans"; return 0; fi
  echo "C23 STOP $(date -u +%FT%TZ): smoke failed: $n picks, $p plans, $tb tracebacks"; return 1
}

# The gate and the hold have never run on a GPU. 128 users on 70 GB fills host memory and forms a queue within minutes, which 128 on 160 GB does not:
# campaign 19 parked 7 reads in its first 30 min. Technical checks only (owned_smoke_check.py), since a stuck read blocks its turn.
owned_ok() {
  local R
  R=$AC/results/$(awk '$1 == "owned_smoke" { print $2 }' "$CD/manifest.txt")
  python3 -I -B "$AC/frozen/oracle_scripts_staging/c23_engine/owned_smoke_check.py" "$R" && { echo "C23 owned smoke ok"; return 0; }
  echo "C23 STOP $(date -u +%FT%TZ): gate and hold smoke failed, see above"; return 1
}

run_arm owned_smoke three_tier_wc_oracle_v2_nu_owned 128 70 1 oracle "" 1800 && owned_ok \
  && run_arm table_smoke three_tier_wc_oracle_v2_nu_table 44 70 0 dist none 1800 && smoke_ok \
  && run_arm jit_exact_c44 three_tier_wc_oracle_v2_nu_owned 44 70 1 oracle "" 7200 \
  && run_arm jit_p50_c44 three_tier_wc_oracle_v2_nu_owned 44 70 0 dist "" 7200 \
  && run_arm jit_exact_c128 three_tier_wc_oracle_v2_nu_owned 128 "" 1 oracle "" 7200 \
  && run_arm jit_p50_c128 three_tier_wc_oracle_v2_nu_owned 128 "" 0 dist "" 7200 \
  && echo "C23 ALL DONE $(date -u +%FT%TZ)"
